import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Button from 'flarum/common/components/Button';
import LogFileListItem from './LogFileListItem';
export default class LogFileList extends Component {
  oninit(vnode) {
    super.oninit(vnode);
    this.attrs.state.loadList();
  }
  view() {
    const state = this.attrs.state;
    if (!state.listLoaded) {
      if (state.listLoading) return m(LoadingIndicator, null);
      return m("div", {
        className: "LogViewerPage--emptyList"
      }, m("p", null, app.translator.trans('ianm-log-viewer.admin.viewer.list_failed')), m(Button, {
        className: "Button",
        icon: "fas fa-redo",
        onclick: () => state.refreshList()
      }, app.translator.trans('ianm-log-viewer.admin.viewer.retry')));
    }
    if (!state.files.length) {
      return m("div", {
        className: "LogViewerPage--emptyList"
      }, m("p", null, app.translator.trans('ianm-log-viewer.admin.viewer.no_log_files')));
    }
    return m("div", {
      className: "LogViewerPage--fileListItems"
    }, state.files.map(file => {
      return m(LogFileListItem, {
        key: file.relativePath(),
        file: file,
        state: state
      });
    }));
  }
}
flarum.reg.add('ianm-log-viewer', 'admin/components/LogFileList', LogFileList);